from src.data_loading import buildFeatureBase, addForwardReturnLabel, sp500Tickersfrom xgboost import XGBClassifierimport pandas as pdimport numpy as npfrom sklearn.metrics import matthews_corrcoef, roc_auc_scoresp500 = sp500Tickers()FEATURE_COLS = ['Daily Return', 'Momentum_,5', 'Momentum_,20', 'Momentum_,60',                'Momentum_,120', 'Volume,20', 'Price_Level_High_252',                'Price_Level_Low_252', 'Relative Strength,20']FORWARD_WINDOWS = [20,60,100,200]# ONE expensive pull, sized to cover the widest horizon in the sweepwindow_data = pd.DataFrame()for start, end in [('2005-01-01',                    '2015-01-01'),                    ('2011-01-01',                     '2021-01-01'),                    ('1995-01-01','2005-01-01')]:                                   print(start)                                   base = buildFeatureBase(sp500.tolist(), start, end,max_forward_window=max(FORWARD_WINDOWS))                                   for i in FORWARD_WINDOWS:                                        print(i)                                        _train = addForwardReturnLabel(base.train, i)                                        _test = addForwardReturnLabel(base.test, i)                                                                                _train = _train.dropna(subset=FEATURE_COLS + [f'Forward Return_,{i}'])                                        _test = _test.dropna(subset=FEATURE_COLS + [f'Forward Return_,{i}'])                                                                                if len(_train) < 30 or len(_test) < 10:                                            print(f"  Skipping window {i}, too few rows (train={len(_train)}, test={len(_test)})")                                            continue                                                                                _train_X = _train[FEATURE_COLS]                                        _train_Y = _train[[f'Forward Return_,{i}']]                                        _test_X = _test[FEATURE_COLS]                                        _test_Y = _test[[f'Forward Return_,{i}']]                                                                                cutoff = np.percentile(_train_Y, 70)                                        _train_Y_binary = np.where(_train_Y > cutoff, 1, 0)                                        _test_Y_binary = np.where(_test_Y > cutoff, 1, 0)                                                                                model = XGBClassifier(n_estimators=100, max_depth=3, learning_rate=0.1)                                        model.fit(_train_X, _train_Y_binary)                                        predict_binary = model.predict(_test_X)                                        predict_proba = model.predict_proba(_test_X)                                                                                mcc = matthews_corrcoef(predict_binary, _test_Y_binary)                                        auc = roc_auc_score(_test_Y_binary, predict_proba[:, 1])                                                                                newd = pd.DataFrame({'Forward': [i],                                                             'mcc': [mcc],                                                             'auc': [auc],                                                             'start':[start],                                                             'end':[end]})                                        window_data = pd.concat([window_data, newd])                                                                        print(window_data)window_data.to_csv("/Users/ggraham/pipe_dream/out/2026_07_28 Forward Window Many Epochs XGBoost Predictions.csv")